-- Shelf rows for every subject and sub-subject (run before 99_apply.sql).
-- Idempotent: re-running only refreshes the labels.
on conflict (slug) do update set
  name = excluded.name,
  description = excluded.description;

-- Legacy shelves leave the taxonomy: flag them instead of renaming, because
-- categories.name is shown on book cards. Books keep their category_id; the
-- storefront simply stops offering these shelves to browse.
alter table public.categories
  add column if not exists is_active boolean not null default true;

update public.categories
   set is_active = slug = any (array['medicine-and-healthcare', 'medicine-and-healthcare--anatomy', 'medicine-and-healthcare--anesthesia', 'medicine-and-healthcare--biochemistry', 'medicine-and-healthcare--cancer', 'medicine-and-healthcare--cardiac-surgery', 'medicine-and-healthcare--cardiology', 'medicine-and-healthcare--community-medicine', 'medicine-and-healthcare--dentistry', 'medicine-and-healthcare--dermatology', 'medicine-and-healthcare--endocrinology', 'medicine-and-healthcare--ent', 'medicine-and-healthcare--forensic-medicine', 'medicine-and-healthcare--gastroenterology', 'medicine-and-healthcare--gyn-and-obs', 'medicine-and-healthcare--hematology', 'medicine-and-healthcare--medical-education', 'medicine-and-healthcare--medical-lab-technology', 'medicine-and-healthcare--medicine', 'medicine-and-healthcare--microbiology-and-genetics', 'medicine-and-healthcare--neurology-and-neurosurgery', 'medicine-and-healthcare--nursing', 'medicine-and-healthcare--ophthalmology', 'medicine-and-healthcare--orthopedics', 'medicine-and-healthcare--pathology', 'medicine-and-healthcare--pediatric-surgery', 'medicine-and-healthcare--pediatrics', 'medicine-and-healthcare--pharmacology', 'medicine-and-healthcare--pharmacy', 'medicine-and-healthcare--physiology', 'medicine-and-healthcare--physiotherapy', 'medicine-and-healthcare--plastic-surgery', 'medicine-and-healthcare--psychiatry', 'medicine-and-healthcare--radiology', 'medicine-and-healthcare--respiratory-diseases', 'medicine-and-healthcare--surgery', 'medicine-and-healthcare--urology-and-nephrology', 'business-and-management-sciences', 'business-and-management-sciences--accounting', 'business-and-management-sciences--administrative-science', 'business-and-management-sciences--banking-and-finance', 'business-and-management-sciences--business-studies', 'business-and-management-sciences--marketing', 'business-and-management-sciences--management-sciences', 'business-and-management-sciences--tourism-and-hotel-management', 'social-